using System;
using System.IO;
using System.Text;
using System.Threading;
using System.Collections.Generic;
using System.Web.Script.Serialization;
using PCLRestore.Runtime;
internal static class VanillaTests {
 static string Json(object value){return new JavaScriptSerializer().Serialize(value);}
 static void Assert(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Reject(Action action){try{action();}catch(InvalidDataException){return;}throw new Exception("unsafe vanilla input accepted");}
 static byte[] Bytes(string s){return Encoding.UTF8.GetBytes(s);}
 static Dictionary<string,object> Obj(string json){return new JavaScriptSerializer().DeserializeObject(json) as Dictionary<string,object>;}
 internal static void Run(Action<string,Action> test){
  test("vanilla catalog retains release snapshot and old versions",()=>{var list=VanillaModel.Catalog("{\"versions\":[{\"id\":\"26.3\",\"type\":\"release\",\"url\":\"https://piston-meta.mojang.com/v1/a.json\",\"sha1\":\""+new string('a',40)+"\"},{\"id\":\"x\",\"type\":\"snapshot\",\"url\":\"https://piston-meta.mojang.com/v1/b.json\",\"sha1\":\""+new string('b',40)+"\"}]}");Assert(list.Count==2&&list[1].Type=="snapshot","catalog categories lost");});
  test("vanilla rejects unsafe names paths and URLs",()=>{foreach(var name in new[]{"../escape","CON","a.","a:b","a\\b","", "LPT1.txt"})Reject(()=>VanillaModel.Name(name));foreach(var path in new[]{"../escape","/root","a/../../x","a:b","x\\..\\escape"})Reject(()=>VanillaModel.Relative(path));Reject(()=>VanillaModel.Url("http://libraries.minecraft.net/a"));Reject(()=>VanillaModel.Url("https://evil.example/a"));});
  test("vanilla rules use ordered allow disallow and Windows architecture",()=>{Assert(!VanillaModel.Allowed(Obj("{\"rules\":[{\"action\":\"allow\",\"os\":{\"name\":\"linux\"}}]}"),"x64"),"linux accepted");Assert(VanillaModel.Allowed(Obj("{\"rules\":[{\"action\":\"allow\"},{\"action\":\"disallow\",\"os\":{\"name\":\"osx\"}}]}"),"x64"),"ordered disallow wrong");Assert(!VanillaModel.Allowed(Obj("{\"rules\":[{\"action\":\"allow\",\"os\":{\"arch\":\"x86\"}}]}"),"x64"),"x86 rule matched x64");});
  test("vanilla library plan includes legacy native classifiers and modern artifacts",()=>{
   var m=Metadata();m["libraries"]=new object[]{Obj("{\"downloads\":{\"artifact\":"+Descriptor("lib.jar","a/b.jar")+",\"classifiers\":{\"natives-windows-64\":"+Descriptor("native.jar","a/n.jar")+"}},\"natives\":{\"windows\":\"natives-windows-${arch}\"}}"),Obj("{\"rules\":[{\"action\":\"allow\",\"os\":{\"name\":\"windows\",\"arch\":\"x86_64\"}}],\"downloads\":{\"artifact\":"+Descriptor("modern.jar","a/modern.jar")+"}}")};
   var plan=VanillaModel.Plan(m,"x64");Assert(plan.Libraries.Count==3,"native or modern artifact missing");
  });
  test("vanilla assets preserve object virtual and legacy resources layout",()=>{var plan=VanillaModel.Assets(Obj("{\"virtual\":true,\"map_to_resources\":true,\"objects\":{\"sound/test.ogg\":{\"hash\":\""+new string('a',40)+"\",\"size\":4}}}"),"legacy");Assert(plan.Files.Count==1&&plan.Copies.Count==2,"legacy asset mapping missing");Reject(()=>VanillaModel.Assets(Obj("{\"objects\":{\"../escape\":{\"hash\":\""+new string('a',40)+"\",\"size\":4}}}"),"x"));});
  test("vanilla full fixture install publishes standard pure version last",()=>Fixture((installer,version,root,calls)=>{installer.Install(version,root,"My Vanilla",CancellationToken.None,null);Assert(File.Exists(Path.Combine(root,"versions/My Vanilla/My Vanilla.jar")),"client missing");Assert(Obj(File.ReadAllText(Path.Combine(root,"versions/My Vanilla/My Vanilla.json")))["id"].ToString()=="My Vanilla","custom id missing");Assert(File.Exists(Path.Combine(root,"libraries/a/test.jar")),"library missing");Assert(File.Exists(Path.Combine(root,"assets/indexes/test.json")),"asset index missing");Assert(File.ReadAllText(Path.Combine(root,"versions/My Vanilla/PCL/config.json")).Contains("ModLoaderVersions"),"pure component manifest missing");}));
  test("vanilla existing version and saves are never overwritten",()=>Fixture((installer,version,root,calls)=>{Directory.CreateDirectory(Path.Combine(root,"versions/keep"));File.WriteAllText(Path.Combine(root,"versions/keep/keep.json"),"mine");Reject(()=>installer.Install(version,root,"keep",CancellationToken.None,null));Assert(File.ReadAllText(Path.Combine(root,"versions/keep/keep.json"))=="mine"&&calls.Count==0,"existing version changed");}));
  test("vanilla corrupt transfer cannot publish installed version",()=>Fixture((installer,version,root,calls)=>{installer.Fetch=(u,p,c)=>File.WriteAllText(p,"corrupt");Reject(()=>installer.Install(version,root,"bad",CancellationToken.None,null));Assert(!Directory.Exists(Path.Combine(root,"versions/bad")),"failed download published version");}));
  test("vanilla cancellation leaves no published version",()=>Fixture((installer,version,root,calls)=>{var cts=new CancellationTokenSource();cts.Cancel();try{installer.Install(version,root,"cancel",cts.Token,null);throw new Exception("cancel ignored");}catch(OperationCanceledException){}Assert(!Directory.Exists(Path.Combine(root,"versions/cancel")),"cancel published version");}));
  test("vanilla cancellation during transfer leaves no published version",()=>Fixture((installer,version,root,calls)=>{var cts=new CancellationTokenSource();var fetch=installer.Fetch;installer.Fetch=(u,p,t)=>{fetch(u,p,t);if(u.EndsWith("client.jar"))cts.Cancel();};try{installer.Install(version,root,"cancel-active",cts.Token,null);throw new Exception("active cancel ignored");}catch(OperationCanceledException){}Assert(!Directory.Exists(Path.Combine(root,"versions/cancel-active")),"active cancellation published version");}));
  test("vanilla corrupt library leaves game version unpublished",()=>Fixture((installer,version,root,calls)=>{var fetch=installer.Fetch;installer.Fetch=(u,p,t)=>{fetch(u,p,t);if(u.EndsWith("lib.jar"))File.WriteAllText(p,"broken library");};Reject(()=>installer.Install(version,root,"bad-library",CancellationToken.None,null));Assert(!Directory.Exists(Path.Combine(root,"versions/bad-library")),"corrupt library published version");}));
  test("vanilla cross-volume installation keeps staging under launcher cache",()=>Fixture((installer,version,root,calls)=>{string destination=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"PCL-Independent-QA-"+Guid.NewGuid().ToString("N"));if(Path.GetPathRoot(destination)==Path.GetPathRoot(root)){Console.WriteLine("SKIP cross-volume fixture requires project and local-app-data on different drives");return;}installer.Install(version,destination,"Cross Drive",CancellationToken.None,null);Assert(File.Exists(Path.Combine(destination,"versions/Cross Drive/Cross Drive.json")),"cross-volume metadata missing");Assert(!File.Exists(Path.Combine(destination,"versions/Cross Drive/.pclrestore-installing")),"publication marker remained");}));
  test("vanilla verified libraries and assets are reused",()=>Fixture((installer,version,root,calls)=>{installer.Install(version,root,"first",CancellationToken.None,null);calls.Clear();installer.Install(version,root,"second",CancellationToken.None,null);Assert(!calls.Contains("https://libraries.minecraft.net/lib.jar")&&!calls.Contains("https://resources.download.minecraft.net/"+Hash("asset").Substring(0,2)+"/"+Hash("asset")),"verified shared data downloaded again");}));
 }
 static string Hash(string s){return VanillaModel.Sha1(Bytes(s));}
 static string Descriptor(string content,string path){return Json(new{url="https://libraries.minecraft.net/"+content,sha1=Hash(content),size=Bytes(content).Length,path=path});}
 static Dictionary<string,object> Metadata(){return Obj("{\"id\":\"test\",\"downloads\":{\"client\":"+Descriptor("client.jar","client.jar")+"},\"assetIndex\":{\"id\":\"test\",\"url\":\"https://piston-meta.mojang.com/index.json\",\"sha1\":\""+new string('a',40)+"\",\"size\":1},\"libraries\":[]}");}
 static void Fixture(Action<VanillaInstaller,VanillaVersion,string,List<string>> action){
  string dir=Path.GetFullPath("tests/UpdaterTests/fixtures/vanilla-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);string root=Path.Combine(dir,"game");
  var data=new Dictionary<string,byte[]>();string index=Json(new{objects=new Dictionary<string,object>{{"a/test.txt",new{hash=Hash("asset"),size=5}}}});data["https://piston-meta.mojang.com/index.json"]=Bytes(index);
  var meta=Metadata();meta["assetIndex"]=new{id="test",url="https://piston-meta.mojang.com/index.json",sha1=Hash(index),size=Bytes(index).Length};meta["libraries"]=new object[]{Obj("{\"downloads\":{\"artifact\":"+Descriptor("lib.jar","a/test.jar")+"}}")};string json=Json(meta);data["https://piston-meta.mojang.com/version.json"]=Bytes(json);data["https://libraries.minecraft.net/client.jar"]=Bytes("client.jar");data["https://libraries.minecraft.net/lib.jar"]=Bytes("lib.jar");data["https://resources.download.minecraft.net/"+Hash("asset").Substring(0,2)+"/"+Hash("asset")]=Bytes("asset");var calls=new List<string>();
  var installer=new VanillaInstaller(Path.Combine(dir,"PCL/Cache/Vanilla"));installer.Fetch=(url,path,ct)=>{lock(calls)calls.Add(url);File.WriteAllBytes(path,data[url]);};var version=new VanillaVersion{Id="test",Type="release",Url="https://piston-meta.mojang.com/version.json",Sha1=Hash(json)};action(installer,version,root,calls);
 }
}
